+      lv_label_set_text(g_home_clock, buf);
+      lv_label_set_text_fmt(g_home_uptime, "up %us - heap %uKB free",
+                            launcher_uptime_sec(), mi.fordblks / 1024);
+    }
+
+  g_fps = g_refr_count;
+  g_refr_count = 0;
+
+  if (g_about_fps != NULL)
+    {
+      lv_label_set_text_fmt(g_about_fps, "fps: %u", g_fps);
+    }
+
+  if (g_about_heap != NULL)
+    {
+      mi = mallinfo();
+      lv_label_set_text_fmt(g_about_heap, "heap: %uKB free",
+                            mi.fordblks / 1024);
+    }
+
+  if (g_home_fps != NULL)
+    {
+      lv_label_set_text_fmt(g_home_fps, "%u fps", g_fps);
+    }
